ruleBookInfo.init:
@js:
(function() {
  var b = JSON.parse(result).body;
  function tagText(tags) {
    if (!tags) return '';
    return tags.map(function(t) { return (typeof t === 'string') ? t : (t.tag || ''); }).filter(function(x) { return !!x; }).join(',');
  }
  if (book.bookUrl.indexOf('/series/') >= 0) {
    var sid = book.bookUrl.match(/series\/(\d+)/)[1];
    return {
      title: b.title || '',
      userName: b.userName || '',
      description: b.description || b.caption || '',
      coverUrl: b.coverUrl || '',
      textCount: b.total || 0,
      tags: tagText(b.tags),
      tocUrl: 'https://www.pixiv.net/ajax/novel/series/' + sid + '/content_titles?lang=zh'
    };
  }
  if (b.seriesNavData && b.seriesNavData.seriesId) {
    return {
      title: b.seriesNavData.title || b.title,
      userName: b.userName || '',
      description: b.description || '',
      coverUrl: b.coverUrl || '',
      textCount: b.textCount || 0,
      tags: tagText(b.tags),
      tocUrl: 'https://www.pixiv.net/ajax/novel/series/' + b.seriesNavData.seriesId + '/content_titles?lang=zh'
    };
  }
  return {
    title: b.title || '',
    userName: b.userName || '',
    description: b.description || '',
    coverUrl: b.coverUrl || '',
    textCount: b.textCount || 0,
    tags: tagText(b.tags),
    tocUrl: book.bookUrl
  };
})();

ruleSearch.bookList:
@js:
(function() {
  var d = JSON.parse(result).body.novel.data;
  return d.map(function(v) {
    var isSeries = !!v.seriesId;
    return {
      name: v.title,
      author: v.userName,
      bookUrl: isSeries ? 'https://www.pixiv.net/ajax/novel/series/' + v.seriesId + '?lang=zh' : 'https://www.pixiv.net/ajax/novel/' + v.id + '?lang=zh',
      coverUrl: v.coverUrl || v.url || '',
      intro: v.description || '',
      kind: (v.tags || []).join(','),
      wordCount: v.textCount || 0,
      lastChapter: isSeries ? (v.seriesTitle || v.title) : v.title
    };
  });
})();

ruleToc.chapterList:
@js:
(function() {
  var b = JSON.parse(result).body;
  if (Array.isArray(b)) {
    return b.map(function(v) {
      return { title: v.title, chapterUrl: 'https://www.pixiv.net/ajax/novel/' + v.id + '?lang=zh' };
    });
  }
  return [{ title: b.title, chapterUrl: book.bookUrl }];
})();
